class Solution:
    def fewestSwaps(self, seats: List[int]) -> int:
        n, t = len(seats), sum(seats)
        best = 0
        for i in range(n):
            inside = sum(seats[(i + j) % n] for j in range(t))
            best = max(best, inside)
        return t - best

