class Solution {
    public int fewestSwaps(int[] seats) {
        int n = seats.length, t = 0, best = 0;
        for (int x : seats) t += x;
        for (int i = 0; i < n; i++) {
            int inside = 0;
            for (int j = 0; j < t; j++) inside += seats[(i + j) % n];
            best = Math.max(best, inside);
        }
        return t - best;
    }
}

